# The site's mark, as arithmetic and outlines, for the one place a stylesheet cannot
# reach.
#
# The words are paths rather than text, and that is the whole point. A card is
# rasterised by librsvg, which ignores font-family: ask it for Inter, for Times New
# Roman, or for a font that does not exist and it draws the same face either way, and
# it tells apart only two weights. A logo set as text is therefore a logo drawn in
# whatever the renderer feels like, stretched to a width measured from a font it never
# loaded. That is exactly how this came out mangled.
#
# These outlines are Inter at weight 800 carrying the stylesheet's own tracking, taken
# from the file the site itself loads. They cannot be substituted, so the mark on a
# card is the mark on the page rather than an impression of it.
#
# Both are drawn in a one-em box with the baseline at y=0, so a size is just a scale.
class ShareCard::Wordmark
  TAN = 0.2691                                    # tan(15.06deg), the angle of the cut
  HEIGHT = 1.9                                    # the field, top to bottom
  CAP = 0.727                                     # where uppercase stops

  GAP = 0.42                                      # white either side of the cut
  ENDCAP = 0.52                                   # white at the closed end
  REVERSED = 0.03                                 # light on dark eats its own space
  AFTER_Y = 0.2029                                # white the font builds in after a Y
  BEFORE_F = 0.0567                               # before an F
  AFTER_T = 0.2099                                # after a T

  # Measured off the outlines below, so the geometry and the drawing can never drift.
  INK_WIDTH = 4.8390
  FIELD_WIDTH = 5.3205

