  # Hung from its right edge and its middle, because a card places the mark in a
  # corner and cares where that corner is, not where the F happens to start.
  def initialize(size:, right:, middle:)
    @size = size.to_f
    @right = right.to_f
    @middle = middle.to_f
  end

  attr_reader :size

  def width = at(raw_width)
  def height = at(raw_height)
  def baseline = at(raw_top + ((raw_height + em(CAP)) / 2))

  def ink_transform = transform(raw_left)
  def field_transform = transform(raw_field_x + padding_left)

  # The field, cut at the angle every clip-path on the site leans at.
  def points
    corners.map { |x, y| [ at(x), at(y) ].join(",") }.join(" ")
  end

  private

  def transform(x)
    "translate(#{at(x)} #{baseline}) scale(#{@size.round(3)})"
  end

  def corners
    left = raw_field_x
    right = left + field_width
    bottom = raw_top + raw_height

    [ [ left + run, raw_top ], [ right, raw_top ], [ right - run, bottom ], [ left, bottom ] ]
  end

  def raw_width = ink_advance + lead + field_width
  def raw_height = em(HEIGHT)
  def raw_left = @right - raw_width
  def raw_top = @middle - (raw_height / 2)
  def raw_field_x = raw_left + ink_advance + lead

  def run = raw_height * TAN
  def field_width = field_advance + padding_left + padding_right

  # Spacing is the white you should see less the white the letter already brings,
  # because a Y opens away from the baseline and an F does not.
  def lead = em(GAP - AFTER_Y) - (run / 2)
  def padding_left = em(GAP - BEFORE_F + REVERSED) + (run / 2)
  def padding_right = em(ENDCAP - AFTER_T) + (run / 2)

  def ink_advance = em(INK_WIDTH)
  def field_advance = em(FIELD_WIDTH)
  def em(value) = value * @size
  def at(value) = value.round(1)
end
